def cs_name(cmd):
    """client->server class name for a command id (or None)."""
    for n in BY_CMD.get(cmd, ()):
        if n.startswith("CS"):
            return n
    return None

def sc_name(cmd):
    """server->client class name for a command id (or None)."""
    for n in BY_CMD.get(cmd, ()):
        if n.startswith("SC"):
            return n
    return None
